sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color1;
uniform float2 point1;
layout(color) uniform half4 color2;
uniform float2 point2;
layout(color) uniform half4 color3;
uniform float2 point3;
layout(color) uniform half4 color4;
uniform float2 point4;
uniform float softness;
uniform float opacity;
uniform float blend;
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float2 p = coord - 0.5 * size;
    float unit = max(max(size.x, size.y), 1.0);
    float power = 2.0 + 6.0 * (1.0 - clamp(softness, 0.0, 1.0));
    float w1 = pow(max(distance(p, point1) / unit, 0.001), -power);
    float w2 = pow(max(distance(p, point2) / unit, 0.001), -power);
    float w3 = pow(max(distance(p, point3) / unit, 0.001), -power);
    float w4 = pow(max(distance(p, point4) / unit, 0.001), -power);
    float4 g = (w1 * float4(color1) + w2 * float4(color2) + w3 * float4(color3) + w4 * float4(color4)) / (w1 + w2 + w3 + w4);
    float3 rgb = mix(base, clamp(blendWith(blend, base, g.rgb), 0.0, 1.0), clamp(opacity, 0.0, 1.0) * g.a);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
